input.new_string:
export function needsRehash(stored, iterations = DEFAULT_ITERATIONS) {
  const parts = String(stored).split('$')
  if (parts.length !== 5) return true
  const [scheme, digest, iterationsRaw] = parts
  if (scheme !== 'pbkdf2' || digest !== DIGEST) return true
  const parsed = Number.parseInt(iterationsRaw, 10)
  if (!Number.isFinite(parsed) || parsed <= 0) return true
  return parsed < iterations
}

  assert.match(stored, /^pbkdf2\$sha256\$600000\$fixed-salt\$/)
  assert.equal(verifyPassword('secret', stored), true)
  assert.equal(verifyPassword('wrong', stored), false)
})

test('旧 100000 次迭代哈希仍可校验，并会被标记为需要迁移', () => {
  const legacy = hashPassword('secret', { iterations: 100_000, salt: 'legacy-salt' })
  assert.equal(verifyPassword('secret', legacy), true)
  assert.equal(needsRehash(legacy), true)
})
